/// <summary>
/// Logic block containing business logic needed to create a movement journal line
/// </summary>
class MwmsLogicBlockCreateMovementJournalLine extends MwmsLogicBlockJournalLinesCommon implements TFMLogicBlockDataCollectionInterface, TFMLogicBlockPrePostDataModifyInterface
{

}

Method.Source:
public static MwmsLogicBlockCreateMovementJournalLine Construct(MWMSAddUpdate _addUpdate = AddUpdate::Add)
{
    MwmsLogicBlockCreateMovementJournalLine movementLineBlock= new MwmsLogicBlockCreateMovementJournalLine();
    movementLineBlock.parmCreateOrUpdate(_addUpdate);
    return movementLineBlock;
}

/// <summary>
/// This method provides the header fields, that are needed to find out which data should be collected.
/// </summary>
/// <returns>A MobReferenceDataConfiguration object, containing registration collectors for the header.</returns>
public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    return this.lockWarehouseInHeader(components.getHeaders());
}

public Set autoCreatedProcesses()
{
    Set ret = super();

    TFMProcess process = TFMProcess::Construct('CreateMovementJournalLine');
    process.addBlock(this);
    process.blockCollection().addBlockAddon(this, new TFMLogicBlockAddonDisableValueTransfers());
    ret.add(Process);
    process = TFMProcess::Construct('MovementJournalLine');
    process.addBlock(MwmsLogicBlockCreateMovementJournalLine::Construct(AddUpdate::Update));
    ret.add(Process);
    return ret;
}

/// <summary>
/// Name of the block Type.
/// </summary>
/// <returns>Name of the block</returns>
public Name blockName()
{
    return "@MobileWMS:CreateorupdateMovementJournalLine";
}

/// <summary>
/// This method gives you the registration collectors for this data collection block.
/// </summary>
/// <returns>A collection of registration collectors.</returns>
public TFMRegistrationCollectors registrationCollectors()
{
    return components.getCollectors();
}

/// <summary>
/// This method is called before the post method, and gives the option to add extra registration collectors for the user to be prompted for before the post method is executed.
/// </summary>
/// <returns>Returns a MobRegistrationCollectors object if the user must be further prompted, otherwise it returns null</returns>
public TFMRegistrationCollectors prePostRegistrationCollectors()
{
    return null;
}

/// <summary>
/// Method to set up tables to be used in the posting. Ensures that addons can be made, that can modify the data of the block before posting, when needed.
/// </summary>
public void preparePost()
{
    this.getTables();
}

